function storedList(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[]}catch(_){return []}}
const state={page:'home',recruiter:null,candidate:null,job:null,compare:new Set(),bookmarks:new Set(storedList('icd-bookmarks'))};
