function formatAiAnswer(value){const lines=String(value||'').replace(/\r/g,'').split('\n'),parts=[];let list=[];const inline=text=>esc(text).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>'),flush=()=>{if(list.length){parts.push(`<ul>${list.join('')}</ul>`);list=[]}};for(const raw of lines){const line=raw.trim();if(!line){flush();continue}const bullet=line.match(/^[-*]\s+(.+)/);if(bullet){list.push(`<li>${inline(bullet[1])}</li>`);continue}flush();const heading=line.match(/^#{1,3}\s+(.+)/);if(heading)parts.push(`<h3>${inline(heading[1])}</h3>`);else if(/^\*\*.+\*\*:?$/.test(line))parts.push(`<h3>${inline(line.replace(/^\*\*|\*\*:?$/g,''))}</h3>`);else parts.push(`<p>${inline(line)}</p>`)}flush();return parts.join('')}
function interviewQuestionMarkup(data){const sections=Array.isArray(data)?[['Interview questions',data]]:Object.entries(data?.questions||data||{}).filter(([,items])=>Array.isArray(items));return sections.map(([title,items])=>`<section><header><h3>${esc(title)}</h3><span>${items.length}</span></header>${items.map((item,index)=>{const question=typeof item==='string'?item:item?.question||'',rubric=typeof item==='object'?item?.what_good_looks_like||item?.rubric||'':'';return `<article><i>${String(index+1).padStart(2,'0')}</i><div><b>${esc(question)}</b>${rubric?`<details><summary>What a strong answer should cover</summary><p>${esc(rubric)}</p></details>`:''}</div></article>`}).join('')}</section>`).join('')||'<div class="designed-empty"><i>✦</i><h3>No questions were returned</h3><p>Try generating the interview guide again.</p></div>'}
