async function openInterviewQuestions(candidateId,candidateName='Candidate'){document.querySelector('#interview-questions-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell question-workspace-shell" id="interview-questions-modal"><section class="candidate-modal question-plan-modal"><button class="modal-close" data-close-questions>×</button><div class="question-plan-head"><div><div class="kicker">Evidence-grounded preparation</div><h2>${esc(candidateName)} interview guide</h2><p>Keep this guide beside the meeting while you interview. Every question is grounded in the role and candidate evidence.</p></div><span>✦ AI preparing</span></div><div class="question-plan-body"><div class="question-loading"><i>✦</i><b>Building a focused interview plan…</b><span>Checking role evidence and candidate-specific signals.</span></div></div></section></div>`);const modal=document.querySelector('#interview-questions-modal'),body=modal.querySelector('.question-plan-body');modal.querySelector('[data-close-questions]').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};try{const result=await api('/api/interview-questions',{method:'POST',body:JSON.stringify({candidate_id:Number(candidateId)})});body.innerHTML=interviewQuestionMarkup(result);modal.querySelector('.question-plan-head>span').textContent='Evidence grounded'}catch(e){body.innerHTML=`<div class="designed-empty question-error"><i>!</i><h3>Could not prepare questions</h3><p>${esc(e.message)}</p><button class="secondary" data-retry-questions>Try again</button></div>`;modal.querySelector('[data-retry-questions]').onclick=()=>openInterviewQuestions(candidateId,candidateName)}}
async function openInterviewCompanion(candidateId,candidateName='Candidate'){if(innerWidth<800)return openInterviewQuestions(candidateId,candidateName);const width=Math.min(480,Math.max(390,Math.round(screen.availWidth*.3))),left=Math.max(0,screen.availWidth-width),companion=window.open('','icd-interview-companion',`popup=yes,width=${width},height=${screen.availHeight},left=${left},top=0,resizable=yes,scrollbars=yes`);if(!companion)return openInterviewQuestions(candidateId,candidateName);companion.document.open();companion.document.write(`<!doctype html><html><head><title>${esc(candidateName)} — Interview guide</title><meta name="viewport" content="width=device-width,initial-scale=1">${[...document.querySelectorAll('link[rel="stylesheet"]')].map(link=>`<link rel="stylesheet" href="${esc(link.href)}">`).join('')}</head><body class="interview-companion"><main><div class="question-plan-head"><div><div class="kicker">Live interview companion</div><h2>${esc(candidateName)}</h2><p>Evidence-grounded questions stay visible beside Google Meet.</p></div><span>✦ AI preparing</span></div><div class="question-plan-body"><div class="question-loading"><i>✦</i><b>Building a focused interview plan…</b><span>Checking role evidence and candidate-specific signals.</span></div></div></main></body></html>`);companion.document.close();try{const result=await api('/api/interview-questions',{method:'POST',body:JSON.stringify({candidate_id:Number(candidateId)})});if(!companion.closed){companion.document.querySelector('.question-plan-body').innerHTML=interviewQuestionMarkup(result);companion.document.querySelector('.question-plan-head>span').textContent='Evidence grounded';companion.focus()}}catch(e){if(!companion.closed)companion.document.querySelector('.question-plan-body').innerHTML=`<div class="designed-empty question-error"><i>!</i><h3>Could not prepare questions</h3><p>${esc(e.message)}</p></div>`}}
