function closeActionMenus(restoreFocus=false){document.querySelectorAll('.job-actions-menu[open]').forEach(menu=>{const panel=menu.querySelector('.card-action-popover');if(panel?.matches(':popover-open'))panel.hidePopover();menu.open=false;menu.querySelector('summary')?.setAttribute('aria-expanded','false');if(restoreFocus)menu.querySelector('summary')?.focus({preventScroll:true})})}
function revealActiveMobilePage(){
  if(!matchMedia('(max-width:900px)').matches)return;
  const nav=root.querySelector('.workspace>aside nav'),active=nav?.querySelector('button.active');
  if(!active)return;
  const bounds=nav.getBoundingClientRect(),item=active.getBoundingClientRect();
  if(item.left<bounds.left)nav.scrollLeft=Math.max(0,nav.scrollLeft+item.left-bounds.left-8);
  else if(item.right>bounds.right)nav.scrollLeft=Math.min(nav.scrollWidth-nav.clientWidth,nav.scrollLeft+item.right-bounds.right+8);
}
function interviewScoreNeedsSync(interview){
  if(interview?.interview_score==null||interview.interview_score==='')return false;
  const candidates=(state.recruiter?.candidates||[]).filter(candidate=>candidate.candidate_name===interview.candidate_name),role=String(interview.job_role||'').trim().toLowerCase();
  const candidate=candidates.find(item=>String(item.job_role||'').trim().toLowerCase()===role)||(candidates.length===1?candidates[0]:null);
  if(!candidate)return false;
  const average=Math.round((Number(candidate.overall_score??candidate.score??0)+Number(interview.interview_score))*5)/10,decision=average>70?'Selected':'Interview Completed';
  if(candidate.interview_score==null||candidate.interview_score===''||Number(candidate.interview_score)!==Number(interview.interview_score)||candidate.decision_status!==decision)return true;
  let profile=candidate.profile_json;if(typeof profile==='string'){try{profile=JSON.parse(profile)}catch(_){profile={}}}
  const email=candidate.email||profile?.email||'';
  return Boolean(email&&(state.recruiter?.applications||[]).some(application=>application.applicant_email===email&&(!candidate.job_id||String(application.job_id)===String(candidate.job_id))&&application.status!==decision));
}
