async function api(url,options={}){pendingRequests++;root.setAttribute('aria-busy','true');try{const r=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})}}),body=await r.json().catch(()=>({}));if(!r.ok){const detail=body.detail,message=typeof detail==='string'?detail:Array.isArray(detail)?detail.map(item=>[item.loc?.slice(-1)[0],item.msg].filter(Boolean).join(': ')).join('; '):r.status===401?'Your session has expired. Please sign in again.':r.status===429?'Too many requests. Please wait a moment and try again.':`This action could not be completed (${r.status}). Please try again.`;throw new Error(message)}return body}finally{pendingRequests--;if(!pendingRequests)root.removeAttribute('aria-busy')}}
