 if(offers){offers.textContent='Download all offer letters';const send=document.createElement('button');send.id='send-offers';send.className='primary full';send.textContent='Send all offers by email →';offers.insertAdjacentElement('afterend',send);send.onclick=async()=>{const ids=[...document.querySelectorAll('[data-offer-candidate]:checked')].map(x=>Number(x.value));if(!ids.length)return note('Choose at least one candidate','error');const payload=offerPayload(ids);send.disabled=true;send.textContent='Sending secure offers…';try{const result=await api('/api/offers/send',{method:'POST',body:JSON.stringify(payload)});note(`${result.sent_count} offers sent${result.failed_count?`, ${result.failed_count} failed`:''}`,result.failed_count?'error':'ok')}catch(e){note(e.message,'error')}finally{send.disabled=false;send.textContent='Send all offers by email →'}}}
