async function refresh(page,message){const samePage=state.page===page;state.recruiter=await api('/api/bootstrap');const ids=new Set(state.recruiter.candidates.map(candidate=>String(candidate.id)));state.compare=new Set([...state.compare].filter(id=>ids.has(id)));state.page=page;state.keepScroll=samePage;renderRecruiter();if(message)note(message)}
function candidateModal(c){if(!c)return;const profile=typeof c.profile_json==='string'?JSON.parse(c.profile_json||'{}'):c.profile_json||{},score=typeof c.score_json==='string'?JSON.parse(c.score_json||'{}'):c.score_json||{};document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell" id="candidate-modal"><section class="candidate-modal"><button class="modal-close" id="modal-close">×</button><div class="candidate-modal-head"><div class="candidate-monogram">${esc((c.candidate_name||'C')[0])}</div><div><div class="kicker">${esc(c.job_role||'Candidate')}</div><h2>${esc(c.candidate_name||c.filename)}</h2><p>${esc(c.email||'')} ${c.phone?'· '+esc(c.phone):''}</p></div><div class="score-ring large" style="--score:${c.score}"><b>${c.score}</b><span>match</span></div></div><div class="evidence-grid"><article><span>Skills match</span><b>${score.breakdown?.skills_match??c.skills_match??'—'}</b></article><article><span>Experience fit</span><b>${score.breakdown?.experience_fit??c.experience_fit??'—'}</b></article><article><span>Education fit</span><b>${score.breakdown?.education_fit??c.education_fit??'—'}</b></article></div><div class="modal-columns"><article><h3>Recruiter summary</h3><p>${esc(score.summary||c.recruiter_summary||'No summary available.')}</p><h3>Experience & education</h3><p>${esc(profile.years_experience||c.years_experience||'Not captured')} · ${esc(profile.education||c.education||'Not captured')}</p></article><article><h3>Matched skills</h3><div class="chips positive">${(c.matched_skills||[]).map(s=>`<span>${esc(s)}</span>`).join('')||'<span>None identified</span>'}</div><h3>Development gaps</h3><div class="chips gaps">${(c.gaps||[]).map(s=>`<span>${esc(s)}</span>`).join('')||'<span>No major gaps</span>'}</div></article></div></section></div>`);document.querySelector('#modal-close').onclick=()=>document.querySelector('#candidate-modal').remove();document.querySelector('#candidate-modal').onclick=e=>{if(e.target.id==='candidate-modal')e.currentTarget.remove()};}
function newJobModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell" id="job-modal"><form class="candidate-modal job-form-modal" id="job-form"><button type="button" class="modal-close" id="job-close">×</button><div class="kicker">New opportunity</div><h2>Create a detailed job</h2><p>Publish a complete role that candidates can understand and trust.</p><div class="form-grid"><div><label>Role title</label><input name="title" required></div><div><label>Department</label><input name="department"></div><div><label>Location</label><input name="location" placeholder="Hybrid / Remote"></div><div><label>Employment type</label><select name="employment_type"><option>Full-time</option><option>Part-time</option><option>Contract</option><option>Internship</option></select></div><div class="wide"><label>Experience level</label><input name="experience_level" placeholder="e.g. 2–5 years"></div><div class="wide"><label>About the role</label><textarea name="description" rows="3"></textarea></div><div class="wide"><label>Responsibilities</label><textarea name="responsibilities" rows="3"></textarea></div><div class="wide"><label>Benefits</label><textarea name="benefits" rows="2"></textarea></div><div class="wide"><label>Required skills</label><input name="skills" placeholder="Python, FastAPI, PostgreSQL"></div></div><button class="primary full">Create and publish role →</button></form></div>`);document.querySelector('#job-close').onclick=()=>document.querySelector('#job-modal').remove();document.querySelector('#job-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f);data.required_skills=(data.skills||'').split(',').map(x=>x.trim()).filter(Boolean);delete data.skills;try{await api('/api/jobs',{method:'POST',body:JSON.stringify(data)});document.querySelector('#job-modal').remove();await refresh('jobs','Job created')}catch(err){note(err.message,'error')}}}
function compareCandidates(items){if(items.length<2)return note('Select at least two candidates to compare','error');document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell" id="compare-modal"><section class="candidate-modal comparison-modal"><button class="modal-close" id="compare-close">×</button><div class="kicker">Side-by-side evidence</div><h2>Candidate comparison</h2><div class="comparison-grid">${items.slice(0,4).map(c=>`<article><div class="candidate-monogram">${esc((c.candidate_name||'C')[0])}</div><h3>${esc(c.candidate_name||c.filename)}</h3><span>${esc(c.job_role||'Role')}</span><strong>${c.score}<small>% match</small></strong><p>${esc(c.years_experience||'Experience not captured')}</p><div class="chips">${(c.matched_skills||[]).slice(0,6).map(s=>`<span>${esc(s)}</span>`).join('')}</div><small>${(c.gaps||[]).length} identified gaps</small><button class="secondary" data-view-from-compare="${c.id}">View full evidence</button></article>`).join('')}</div></section></div>`);document.querySelector('#compare-close').onclick=()=>document.querySelector('#compare-modal').remove();document.querySelector('#compare-modal').onclick=e=>{if(e.target.id==='compare-modal')e.currentTarget.remove()};document.querySelectorAll('[data-view-from-compare]').forEach(b=>b.onclick=()=>{document.querySelector('#compare-modal').remove();candidateModal(state.recruiter.candidates.find(c=>String(c.id)===b.dataset.viewFromCompare))})}
function shareJobModal(id){const url=`${location.origin}/?apply=${id}`;document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell" id="share-modal"><section class="candidate-modal share-modal"><button class="modal-close" id="share-close">×</button><div class="kicker">Public application</div><h2>Share this opportunity</h2><p>Candidates can scan the QR code or open the secure public link.</p><img src="/api/jobs/${id}/qr" alt="Application QR code"><input value="${esc(url)}" readonly><div class="row"><button class="secondary" id="copy-job-link">Copy link</button><a class="primary button-link" href="/api/jobs/${id}/qr" download="job-${id}-qr.png">Download QR</a></div></section></div>`);document.querySelector('#share-close').onclick=()=>document.querySelector('#share-modal').remove();document.querySelector('#copy-job-link').onclick=async()=>{await navigator.clipboard.writeText(url);note('Public application link copied')}}
function editJobModal(job){newJobModal();const form=document.querySelector('#job-form');form.querySelector('h2').textContent='Edit job details';['title','department','location','employment_type','experience_level','description','responsibilities','benefits'].forEach(k=>{if(form.elements[k])form.elements[k].value=job[k]||''});form.elements.skills.value=(job.required_skills||[]).join(', ');form.querySelector('button.primary').textContent='Save job changes →';form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.required_skills=(data.skills||'').split(',').map(x=>x.trim()).filter(Boolean);delete data.skills;try{await api('/api/jobs/'+job.id,{method:'PATCH',body:JSON.stringify(data)});document.querySelector('#job-modal').remove();await refresh('jobs','Job updated')}catch(err){note(err.message,'error')}}}

function enhanceRecruiterRegistration(){const panel=root.querySelector('.recruiter-access .auth-panel');if(!panel||panel.querySelector('#register-company'))return;panel.insertAdjacentHTML('beforeend',`<div class="registration-entry"><span>New organization?</span><button class="secondary" id="register-company">Submit company for approval →</button><small>Your workspace appears only after owner review.</small></div>`);document.querySelector('#register-company').onclick=companyRegistrationModal}

function companyRegistrationModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell" id="registration-modal"><form class="candidate-modal registration-modal" id="registration-form"><button type="button" class="modal-close" id="registration-close">×</button><div class="kicker">Organization onboarding</div><h2>Request a secure workspace.</h2><p>Share your organization details. Receive a secure code now to track your request. Workspace access activates only after owner approval.</p><div class="form-grid"><div><label>Company name *</label><input name="company_name" required minlength="2"></div><div><label>Contact person *</label><input name="contact_name" required minlength="2"></div><div><label>Business email *</label><input name="business_email" type="email" required></div><div><label>Phone</label><input name="phone"></div><div class="wide"><label>Company website</label><input name="website" type="url" placeholder="https://company.com"></div><div><label>Industry</label><input name="industry" placeholder="Technology"></div><div><label>Company size</label><select name="company_size"><option value="">Select size</option><option>1–10</option><option>11–50</option><option>51–200</option><option>201–1000</option><option>1000+</option></select></div><div class="wide"><label>Registration number <small>Optional for prototype</small></label><input name="registration_number" placeholder="CIN, LLPIN, GSTIN or local registration"></div><div class="wide"><label>About your hiring needs</label><textarea name="message" rows="3"></textarea></div></div><div class="approval-note"><i>⌛</i><span><b>Owner approval required</b>Your company remains private while the request is reviewed.</span></div><button class="primary full">Submit registration request →</button></form></div>`);document.querySelector('#registration-close').onclick=()=>document.querySelector('#registration-modal').remove();document.querySelector('#registration-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter,data=Object.fromEntries(new FormData(e.target));button.disabled=true;button.textContent='Submitting securely…';try{const result=await api('/api/company-registrations',{method:'POST',body:JSON.stringify(data)});document.querySelector('#registration-modal').remove();registrationTracker(data.business_email,result.access_code,true)}catch(err){note(err.message,'error');button.disabled=false;button.textContent='Submit registration request →'}}}

function ownerLogin(){show(`<main class="owner-login"><section>${logo}<div class="owner-eyebrow"><i></i><span>Private administration</span></div><h1>Protect every<br><em>trusted workplace.</em></h1><p>One private command centre to verify organizations, protect candidate trust, and approve secure recruiter access.</p><div class="owner-trust-row"><span>Verified owner identity</span><span>Encrypted access</span></div><button class="google-login" id="owner-google"><span class="google-mark"></span><b>Continue with Google</b></button><button class="back" id="owner-back">← Return to platform</button></section><aside><span>Protected workspace</span><h2>Review every organization before it reaches candidates.</h2><div><b>✓ Private owner access</b><b>✓ Approval before access code</b><b>✓ Lifetime access preserved</b></div></aside></main>`);document.querySelector('#owner-google').onclick=()=>location.assign('/api/candidate/google?owner=true');document.querySelector('#owner-back').onclick=welcome}

async function ownerPortal(){let data;try{data=await api('/api/owner/registrations')}catch(_){ownerLogin();return}const pending=data.registrations.filter(x=>x.status==='pending'),reviewed=data.registrations.filter(x=>x.status!=='pending'),approved=data.registrations.filter(x=>x.status==='approved');show(`<main class="owner-portal"><header>${logo}<nav class="owner-nav"><a href="#owner-companies">Companies</a><a href="#owner-review">Approvals</a><a href="#owner-history">History</a></nav><div><span>Authenticated owner</span><b>${esc(data.owner_email)}</b></div><button class="secondary" id="owner-signout">Sign out</button></header><section class="owner-hero"><div><div class="kicker pale">Platform governance</div><h1>Company command centre</h1><p>See every approved organization, review new requests, and keep workspace information complete and trustworthy.</p></div><div class="owner-stats"><article><strong>${data.companies.length}</strong><span>Active companies</span></article><article><strong>${pending.length}</strong><span>Pending review</span></article><article><strong>${approved.length}</strong><span>Approved requests</span></article></div></section><section class="owner-directory" id="owner-companies"><div class="owner-section-head owner-directory-head"><div><div class="kicker">Company directory</div><h2>All approved organizations</h2><p>Complete identity, contact, registration, access, and workspace details.</p></div><div class="owner-directory-tools"><label><span>⌕</span><input id="owner-company-search" placeholder="Search companies" aria-label="Search approved companies"></label><em id="owner-company-count">${data.companies.length} total</em></div></div><div class="owner-company-grid">${data.companies.map(c=>ownerCompanyCard(c,data.registrations)).join('')||'<div class="designed-empty"><i>◇</i><h3>No approved companies yet</h3><p>Approved organization profiles will appear here.</p></div>'}</div><div class="designed-empty owner-search-empty" id="owner-search-empty" hidden><i>⌕</i><h3>No matching companies</h3><p>Try another company, industry, or email.</p></div></section><section class="owner-review-section" id="owner-review"><div class="owner-section-head"><div><div class="kicker">Review queue</div><h2>${pending.length} pending organization${pending.length===1?'':'s'}</h2><p>Verify company information before granting recruiter access.</p></div><span class="pending-count">${pending.length} awaiting action</span></div><div class="owner-review-grid">${pending.map(ownerRegistrationCard).join('')||'<div class="designed-empty"><i>✓</i><h3>Review queue is clear</h3><p>New company requests will appear here automatically.</p></div>'}</div></section><section class="panel owner-history" id="owner-history"><div class="owner-section-head compact"><div><div class="kicker">Approval history</div><h2>Reviewed requests</h2></div><span>${reviewed.length} reviewed</span></div>${reviewed.map(r=>`<article><div><b>${esc(r.company_name)}</b><span>${esc(r.business_email)}</span></div><span class="owner-status ${r.status}">${esc(r.status)}</span><small>${r.reviewed_at?new Date(r.reviewed_at).toLocaleDateString():(r.access_code?'Workspace access issued':'Review complete')}</small></article>`).join('')||'<div class="designed-empty"><i>↗</i><h3>No review history yet</h3><p>Completed decisions will be recorded here.</p></div>'}</section></main>`);document.querySelector('#owner-signout').onclick=async()=>{await api('/api/candidate/session',{method:'DELETE'});welcome()};document.querySelectorAll('[data-owner-decision]').forEach(b=>b.onclick=()=>ownerDecision(b.dataset.registration,b.dataset.ownerDecision));document.querySelectorAll('[data-company-toggle]').forEach(b=>b.onclick=()=>{const card=b.closest('.owner-company-card'),open=card.classList.toggle('expanded');b.textContent=open?'Hide details ↑':'View all details ↓'});const search=document.querySelector('#owner-company-search');if(search)search.oninput=()=>{const q=search.value.trim().toLowerCase(),cards=[...document.querySelectorAll('.owner-company-card')];cards.forEach(c=>c.hidden=!c.dataset.search.includes(q));const visible=cards.filter(c=>!c.hidden).length;document.querySelector('#owner-company-count').textContent=`${visible} shown`;document.querySelector('#owner-search-empty').hidden=visible>0}}

function ownerCompanyCard(c,registrations){const r=registrations.find(x=>String(x.company_id||'')===String(c.id||''))||registrations.find(x=>(x.company_name||'').toLowerCase()===(c.name||'').toLowerCase())||{},approvedAt=c.approved_at||r.reviewed_at,website=c.website??r.website??'',details=[['Current access code',c.access_code||'Not issued'],['Industry',(c.industry??r.industry)||'Not supplied'],['Company size',(c.company_size??r.company_size)||'Not supplied'],['Contact person',r.contact_name||'Not supplied'],['Business email',r.business_email||c.email||'Not supplied'],['Registration number',r.registration_number||'Not supplied'],['Billing plan',c.billing_plan||'Standard workspace'],['Approved on',approvedAt?new Date(approvedAt).toLocaleDateString():'Not recorded'],['Approved by',c.approved_by||'Platform owner']],search=[c.name,c.industry,r.contact_name,r.business_email,website].filter(Boolean).join(' ').toLowerCase();return `<article class="owner-company-card" data-search="${esc(search)}"><div class="owner-company-head"><div class="company-mark">${mark(c)}</div><div><span class="owner-company-label">Approved organization</span><h3>${esc(c.name||'Organization')}</h3><p>${esc((c.industry??r.industry)||'Industry not supplied')}</p></div><span class="owner-status approved" >${c.verification_status==='suspended'?'Deactivated':'Active'}</span></div><div class="owner-company-primary"><div><small>Website</small>${website?`<a href="${esc(website.startsWith('http')?website:'https://'+website)}" target="_blank" rel="noopener">${esc(website)} ↗</a>`:'<b>Not supplied</b>'}</div><div><small>Company size</small><b>${esc((c.company_size??r.company_size)||'Not supplied')}</b></div><div><small>Recruiter access</small><b>${r.access_code?'Access code issued':'Workspace active'}</b></div></div><div class="owner-company-details">${details.map(([label,value])=>`<div><small>${label}</small><b>${esc(value)}</b></div>`).join('')}<div class="wide"><small>Workspace ID</small><b>${esc(c.id||'Not available')}</b></div><div class="wide"><small>Company message</small><b>${esc(r.message||'No registration message supplied.')}</b></div><div class="wide"><small>Owner review notes</small><b>${esc(r.review_notes||'No internal notes recorded.')}</b></div></div><button type="button" class="danger" data-deactivate-company="${esc(c.id)}" ${c.verification_status==='suspended'?'disabled':''}>${c.verification_status==='suspended'?'Deactivated':'Deactivate company'}</button><button class="owner-company-toggle" data-company-toggle>View all details ↓</button></article>`}

function ownerRegistrationCard(r){return `<article class="owner-review-card"><div class="owner-review-head"><div class="company-mark"><span>${esc(r.company_name[0])}</span></div><div><h3>${esc(r.company_name)}</h3><span>${esc(r.industry||'Industry not supplied')} · ${esc(r.company_size||'Size not supplied')}</span></div><span class="owner-status pending">Pending</span></div><div class="owner-detail-grid"><span><small>Contact</small><b>${esc(r.contact_name)}</b></span><span><small>Business email</small><b>${esc(r.business_email)}</b></span><span><small>Website</small><b>${esc(r.website||'Not supplied')}</b></span><span><small>Registration</small><b>${esc(r.registration_number||'Prototype review')}</b></span></div>${r.message?`<p>${esc(r.message)}</p>`:''}<label>Review notes</label><textarea data-owner-notes="${r.id}" rows="2" placeholder="Optional internal review note"></textarea><div class="row"><button class="danger" data-owner-decision="rejected" data-registration="${r.id}">Reject</button><button class="primary" data-owner-decision="approved" data-registration="${r.id}">Approve & create access code →</button></div></article>`}

async function ownerDecision(id,decision){if(!confirm(`${decision==='approved'?'Approve':'Reject'} this organization?`))return;const notes=document.querySelector(`[data-owner-notes="${id}"]`)?.value||'';try{const result=await api(`/api/owner/registrations/${id}/decision`,{method:'POST',body:JSON.stringify({decision,notes})});if(result.access_code)alert(`Organization approved. Access code: ${result.access_code}\n\nShare this code securely with the company contact.`);note(`Organization ${decision}`);ownerPortal()}catch(e){note(e.message,'error')}}

function registrationTracker(email='',code='',receipt=false){
  document.querySelector('#tracking-modal')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell" id="tracking-modal"><form class="candidate-modal registration-modal" id="tracking-form"><button type="button" class="modal-close" aria-label="Close">×</button><div class="kicker">Organization approval</div><h2>${receipt?'Request submitted. Save your code.':'Track your request'}</h2><p>This code tracks your approval and unlocks your workspace only after the owner approves it. Keep it private.</p><label>Business email<input name="business_email" type="email" required value="${esc(email)}"></label><label>Access code<input name="access_code" required minlength="4" maxlength="4" inputmode="numeric" pattern="[0-9]{4}" autocomplete="off" value="${esc(code)}"></label><button class="primary full">Check approval status →</button><section id="tracking-result" aria-live="polite">${receipt?'<p>Pending owner review. Save this code before closing this page.</p>':''}</section></form></div>`);
  const form=document.querySelector('#tracking-form');form.querySelector('.modal-close').onclick=()=>document.querySelector('#tracking-modal').remove();
  form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const data=Object.fromEntries(new FormData(form)),result=form.querySelector('#tracking-result');try{const status=await api('/api/company-registrations/track',{method:'POST',body:JSON.stringify(data)});result.innerHTML=`<h3>${esc(status.company_name)}</h3><p><b>${status.status==='approved'?'Approved':status.status==='rejected'?'Not approved':'Pending owner review'}</b></p><p>${status.status==='approved'?'Your workspace is ready. Continue using the same code.':status.status==='rejected'?'Your request was not approved. Contact the platform owner for clarification.':'Your request is being reviewed. Workspace access is locked until approval.'}</p>${status.status==='approved'&&status.company_id?'<button type="button" class="primary" id="tracking-enter">Open recruiter workspace →</button>':''}`;const enter=result.querySelector('#tracking-enter');if(enter)enter.onclick=async()=>{enter.disabled=true;try{await api('/api/session/recruiter',{method:'POST',body:JSON.stringify({company_id:status.company_id,access_code:data.access_code})});document.querySelector('#tracking-modal').remove();await loadRecruiter()}catch(err){note(err.message,'error');enter.disabled=false}};}catch(err){result.textContent=err.message;}finally{button.disabled=false}};
}
function mountLogoEditors(){
  document.querySelectorAll('[data-deactivate-company]').forEach(button=>{if(button.dataset.bound)return;button.dataset.bound='1';button.onclick=async()=>{if(!confirm('Deactivate this company? Recruiter access will stop. All records will be preserved.'))return;button.disabled=true;try{await api(`/api/owner/companies/${button.dataset.deactivateCompany}/deactivate`,{method:'POST'});await ownerPortal()}catch(err){note(err.message,'error');button.disabled=false}}});
  const accessPanel=document.querySelector('.recruiter-access .auth-panel');
  if(accessPanel&&!accessPanel.querySelector('[data-track-request]')){const track=document.createElement('button');track.type='button';track.className='secondary full';track.dataset.trackRequest='';track.textContent='Already applied? Track approval →';track.onclick=()=>registrationTracker();accessPanel.append(track);}
  const directoryTools=document.querySelector('.owner-directory-tools');
  if(directoryTools&&!directoryTools.querySelector('[data-refresh-companies]')){
    const refresh=document.createElement('button');refresh.type='button';refresh.className='secondary';refresh.dataset.refreshCompanies='';refresh.textContent='↻ Refresh details';refresh.onclick=()=>ownerPortal();directoryTools.append(refresh);
  }
  document.querySelectorAll('#registration-form,#company-settings').forEach(form=>{
    if(form.querySelector('.company-logo-editor'))return;
    const current=form.id==='company-settings'?(state.recruiter?.company?.logo_base64||''):'';
    const editor=document.createElement('section');editor.className='company-logo-editor';
    editor.innerHTML=`<div class="logo-upload-preview">${current?`<img src="data:image/png;base64,${esc(current)}" alt="Current company logo">`:'<span>◇</span>'}</div><div><label>Company logo<input type="file" accept="image/png,image/jpeg,image/webp" aria-label="Upload company logo"></label><small>PNG, JPG or WebP · Up to 2 MB. Used across your workspace and company communications.</small><p role="status" aria-live="polite"></p></div><input type="hidden" name="logo_base64" value="${esc(current)}">`;
    const anchor=form.querySelector('.form-grid')||form.querySelector('label');form.insertBefore(editor,anchor);
    const fileInput=editor.querySelector('input[type=file]'),value=editor.querySelector('input[type=hidden]'),status=editor.querySelector('[role=status]');
    let busy=false;form.addEventListener('submit',e=>{if(busy){e.preventDefault();e.stopImmediatePropagation();status.textContent='Please wait for the logo preview.'}},true);
    fileInput.onchange=async()=>{
      const file=fileInput.files[0];if(!file)return;
      if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){status.textContent='Choose a PNG, JPG or WebP under 2 MB.';fileInput.value='';return;}
      busy=true;status.textContent='Preparing logo…';const url=URL.createObjectURL(file);
      try{const img=new Image();img.src=url;await img.decode();if(img.width*img.height>16000000)throw Error('Image dimensions too large');const scale=Math.min(1,512/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/png');value.value=data.split(',')[1];editor.querySelector('.logo-upload-preview').innerHTML=`<img src="${data}" alt="New company logo preview">`;status.textContent='Logo ready. Submit the form to save it.';}catch(_){status.textContent='This image could not be read. Choose another logo.';fileInput.value='';}finally{busy=false;URL.revokeObjectURL(url);}
    };
  });
}
new MutationObserver(mountLogoEditors).observe(document.body,{childList:true,subtree:true});
const params=new URLSearchParams(location.search),knownPath=['/','/index.html'].includes(location.pathname);knownPath?(params.has('owner')?ownerPortal():params.has('candidate')?candidateEntry():params.has('recruiter')?recruiterGate():welcome()):notFound();
